    13	import {appendParam} from '@libs/Url';
    14	import CONST from '@src/CONST';
    15	import type {TranslationPaths} from '@src/languages/types';
    16	import type {Route} from '@src/ROUTES';
    17	import type SCREENS from '@src/SCREENS';
    18	
    19	type CountrySelectionPageProps = StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.SETTINGS.PROFILE.ADDRESS_COUNTRY>;
    20	
    21	function CountrySelectionPage({route, navigation}: CountrySelectionPageProps) {
    22	    const [searchValue, setSearchValue] = useState('');
    23	    const {translate} = useLocalize();
    24	    const currentCountry = route.params.country;
    25	
    26	    const countries = useMemo(
    27	        () =>
    28	            Object.keys(CONST.ALL_COUNTRIES).map((countryISO) => {
    29	                const countryName = translate(`allCountries.${countryISO}` as TranslationPaths);
    30	                return {
    31	                    value: countryISO,
    32	                    keyForList: countryISO,
    33	                    text: countryName,
    34	                    isSelected: currentCountry === countryISO,
    35	                    searchValue: StringUtils.sanitizeString(`${countryISO}${countryName}`),
    36	                };
    37	            }),
    38	        [translate, currentCountry],
    39	    );
    40	
    41	    const searchResults = searchCountryOptions(searchValue, countries);
    42	    const headerMessage = searchValue.trim() && !searchResults.length ? translate('common.noResultsFound') : '';
    43	
    44	    const selectCountry = useCallback(
    45	        (option: CountryData) => {
    46	            const backTo = route.params.backTo ?? '';
    47	            // Check the navigation state and "backTo" parameter to decide navigation behavior
    48	            if (navigation.getState().routes.length === 1 && !backTo) {
    49	                // If there is only one route and "backTo" is empty, go back in navigation
    50	                Navigation.goBack();
    51	            } else if (!!backTo && navigation.getState().routes.length === 1) {
    52	                // If "backTo" is not empty and there is only one route, go back to the specific route defined in "backTo" with a country parameter
    53	                Navigation.goBack(appendParam(backTo, 'country', option.value));
    54	            } else {
    55	                // Otherwise, navigate to the specific route defined in "backTo" with a country parameter
    56	                Navigation.navigate(appendParam(backTo, 'country', option.value));
    57	            }
    58	        },
    59	        [route, navigation],
    60	    );
    61	
    62	    return (
    63	        <ScreenWrapper
    64	            testID={CountrySelectionPage.displayName}
    65	            includeSafeAreaPaddingBottom={false}
    66	        >
    67	            <HeaderWithBackButton
    68	                title={translate('common.country')}
    69	                shouldShowBackButton
    70	                onBackButtonPress={() => {
    71	                    const backTo = route.params.backTo ?? '';
    72	                    const backToRoute = backTo ? `${backTo}?country=${currentCountry}` : '';
    73	                    Navigation.goBack(backToRoute as Route);
    74	                }}
    75	            />
    76	
    77	            <SelectionList
    78	                headerMessage={headerMessage}
    79	                textInputLabel={translate('common.country')}
    80	                textInputValue={searchValue}
    81	                sections={[{data: searchResults}]}
    82	                ListItem={RadioListItem}
    83	                onSelectRow={selectCountry}
    84	                shouldSingleExecuteRowSelect
    85	                onChangeText={setSearchValue}
    86	                initiallyFocusedOptionKey={currentCountry}
    87	                shouldUseDynamicMaxToRenderPerBatch
    88	            />
    89	        </ScreenWrapper>
    90	    );
    91	}
    92	
    93	CountrySelectionPage.displayName = 'CountrySelectionPage';
    94	
    95	export default CountrySelectionPage;
    96
